use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageVersionVO;
use Civi\Lughauth\Features\Notification\Message\Application\Usecase\Retrieve\MessageRetrieveResult;
use PHPUnit\Framework\TestCase;

final class MessageRetrieveResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new MessageRetrieveResult();
        $targetOneValue = 'one';
        $targetOtherValue = 'other';
        $copy = $value->target($targetOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getTarget());
        $this->assertNotEquals('other', $value->getTarget());
        $this->assertEquals('one', $value->getTargetOrDefault(MessageTargetVO::from($targetOtherValue))->value());
        $this->assertNotEquals('other', $value->getTargetOrDefault(MessageTargetVO::from($targetOtherValue))->value());
        $value->unsetTarget();
        $this->assertEquals('other', $value->getTargetOrDefault(MessageTargetVO::from($targetOtherValue))->value());
        $this->assertNotEquals('one', $value->getTargetOrDefault(MessageTargetVO::from($targetOtherValue))->value());
        $tenantOneValue = new TenantRef('one');
        $tenantOtherValue = new TenantRef('other');
        $copy = $value->tenant($tenantOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantRef('one'), $value->getTenant());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenant());
        $this->assertEquals(new TenantRef('one'), $value->getTenantOrDefault(MessageTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenantOrDefault(MessageTenantVO::from($tenantOtherValue))->value());
        $value->unsetTenant();
        $this->assertEquals(new TenantRef('other'), $value->getTenantOrDefault(MessageTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('one'), $value->getTenantOrDefault(MessageTenantVO::from($tenantOtherValue))->value());
        $urgentOneValue = true;
        $urgentOtherValue = false;
        $copy = $value->urgent($urgentOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isUrgent());
        $this->assertNotEquals(false, $value->isUrgent());
        $this->assertEquals(true, $value->getUrgentOrDefault(MessageUrgentVO::from($urgentOtherValue))->value());
        $this->assertNotEquals(false, $value->getUrgentOrDefault(MessageUrgentVO::from($urgentOtherValue))->value());
        $value->unsetUrgent();
        $this->assertEquals(false, $value->getUrgentOrDefault(MessageUrgentVO::from($urgentOtherValue))->value());
        $this->assertNotEquals(true, $value->getUrgentOrDefault(MessageUrgentVO::from($urgentOtherValue))->value());
        $contentOneValue = 'one';
        $contentOtherValue = 'other';
        $copy = $value->content($contentOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getContent());
        $this->assertNotEquals('other', $value->getContent());
        $this->assertEquals('one', $value->getContentOrDefault(MessageContentVO::from($contentOtherValue))->value());
        $this->assertNotEquals('other', $value->getContentOrDefault(MessageContentVO::from($contentOtherValue))->value());
        $value->unsetContent();
        $this->assertEquals('other', $value->getContentOrDefault(MessageContentVO::from($contentOtherValue))->value());
        $this->assertNotEquals('one', $value->getContentOrDefault(MessageContentVO::from($contentOtherValue))->value());
        $retriesOneValue = 1;
        $retriesOtherValue = 2;
        $copy = $value->retries($retriesOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getRetries());
        $this->assertNotEquals(2, $value->getRetries());
        $this->assertEquals(1, $value->getRetriesOrDefault(MessageRetriesVO::from($retriesOtherValue))->value());
        $this->assertNotEquals(2, $value->getRetriesOrDefault(MessageRetriesVO::from($retriesOtherValue))->value());
        $value->unsetRetries();
        $this->assertEquals(2, $value->getRetriesOrDefault(MessageRetriesVO::from($retriesOtherValue))->value());
        $this->assertNotEquals(1, $value->getRetriesOrDefault(MessageRetriesVO::from($retriesOtherValue))->value());
        $createdAtOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $createdAtOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->createdAt($createdAtOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAt());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAt());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAtOrDefault(MessageCreatedAtVO::from($createdAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAtOrDefault(MessageCreatedAtVO::from($createdAtOtherValue))->value());
        $value->unsetCreatedAt();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAtOrDefault(MessageCreatedAtVO::from($createdAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAtOrDefault(MessageCreatedAtVO::from($createdAtOtherValue))->value());
        $sendAtOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $sendAtOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->sendAt($sendAtOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getSendAt());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getSendAt());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getSendAtOrDefault(MessageSendAtVO::from($sendAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getSendAtOrDefault(MessageSendAtVO::from($sendAtOtherValue))->value());
        $value->unsetSendAt();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getSendAtOrDefault(MessageSendAtVO::from($sendAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getSendAtOrDefault(MessageSendAtVO::from($sendAtOtherValue))->value());
        $lockAtOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $lockAtOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->lockAt($lockAtOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getLockAt());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getLockAt());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getLockAtOrDefault(MessageLockAtVO::from($lockAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getLockAtOrDefault(MessageLockAtVO::from($lockAtOtherValue))->value());
        $value->unsetLockAt();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getLockAtOrDefault(MessageLockAtVO::from($lockAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getLockAtOrDefault(MessageLockAtVO::from($lockAtOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrDefault(MessageVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrDefault(MessageVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrDefault(MessageVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrDefault(MessageVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
